/**
 * Readers and Writers problem prioritizing writers
 *
 * @author Letícia Mazzo Portela
 * @since Sep/2020
 */
class ReaderWriter {
    int numWriters = 0, numReaders = 0, count = 0;
    Semaphore mutex = new Semaphore(1);
    Semaphore wlock = new Semaphore(1);
    Semaphore rlock = new Semaphore(1);

    public void startRead() throws InterruptedException {
        rlock.acquire();
    }

    public void endRead() {
        rlock.release();
    }

    public void startWrite() throws InterruptedException {
        mutex.acquire();
        numWriters++;
        count++;

        if (numWriters == 1) {
            rlock.acquire();
        }

        mutex.release();
    }

    public void endWrite() throws InterruptedException {
        mutex.acquire();
        numWriters--;

        if (numWriters == 0) {
            rlock.release();
        }

        mutex.release();
    }
}

