/**
 * Counter accessed by multiple threads controlled by lock
 *
 * @author Letícia Mazzo Portela
 * @since Sep/2020
 */
class Counter {
    public int count = 0;
    private final int min, max;
    private final Lock lock;

    public Counter(Lock lock, int min, int max) {
        this.lock = lock;
        this.min = min;
        this.max = max;
    }

    public void increment() {
        lock.lock();

        try {
            if (count <= max) {
                count++;
            }
        } finally {
            lock.unlock();
        }
    }

    public void decrement() {
        lock.lock();

        try {
            if (count >= min) {
                count--;
            }
        } finally {
            lock.unlock();
        }
    }
}

class ThreadController extends Thread {
    private final Counter counter;
    private final int min, max;

    ThreadController(Counter counter, int min, int max) {
        this.counter = counter;
        this.min = min;
        this.max = max;
    }

    @Override
    public void run() {
        final String name = Thread.currentThread().getName();

        while (counter.count <= max) {
            counter.increment();
            System.out.println("Counter increased to " + counter.count + " for thread " + name);
        }

        while (counter.count >= min) {
            counter.decrement();
            System.out.println("Counter decremented to " + counter.count + " for thread " + name);
        }
    }
}

class LockCounter {
    public static void main(final String[] args) {
        final Thread[] threads = new Thread[3];
        final Counter counter = new Counter(new ReentrantLock(), 1, 5);

        for (int n = 0; n < threads.length; n += 1) {
            final ThreadController tc = new ThreadController(counter, 1, 5);
            threads[n] = new Thread(tc);
            System.out.println("Start Thread " + threads[n].getName());
            threads[n].start();
        }
    }
}

import java.util.Random;
import java.util.concurrent.locks.*;

/**
 * SharedFifoQueue using Conditions to control whether the queue is empty or full
 *
 * @author Letícia Mazzo Portela
 * @since Sep/2020
 */
class SharedFifoQueue {
    private final int size;
    private Integer[] items;
    private final Lock lock = new ReentrantLock();
    private final Condition notEmpty = lock.newCondition();
    private final Condition notFull = lock.newCondition();
    private int start, end, totalItems;

    SharedFifoQueue(int size) {
        this.size = size;
        this.items = new Integer[size];
    }

    public void put(int n) throws InterruptedException {
        lock.lock();

        try {
            while (totalItems == size) {
                notFull.await();
            }

            items[start] = n;
            start = ++start % items.length;
            totalItems += 1;

            notEmpty.signal();
        } finally {
            lock.unlock();
        }
    }

    public Integer pop() throws InterruptedException {
        lock.lock();

        try {
            while (totalItems == 0) {
                notEmpty.await();
            }

            int element = items[end];
            end = ++end % items.length;
            totalItems -= 1;

            notFull.signal();
            return element;
        } finally {
            lock.unlock();
        }
    }
}

class ProducerThread extends Thread {
    private final SharedFifoQueue sfq;
    private final Random r = new Random();

    ProducerThread(SharedFifoQueue sfq) {
        this.sfq = sfq;
    }

    @Override
    public void run() {
        final String name = Thread.currentThread().getName();

        while (true) {
            try {
                sfq.put(r.nextInt((100 - 1) + 1) + 1);
                System.out.println("Thread " + name + " is producing...");

                Thread.sleep(3000);
            } catch (Exception e) {
                System.out.println("Exception: " + e);
            }
        }
    }
}

class ConsumerThread extends Thread {
    private final SharedFifoQueue sfq;

    ConsumerThread(SharedFifoQueue sfq) {
        this.sfq = sfq;
    }

    @Override
    public void run() {
        final String name = Thread.currentThread().getName();

        while (true) {
            try {
                final Integer element = sfq.pop();
                System.out.println("Thread " + name + " consumed the element " + element);

                Thread.sleep(3000);
            } catch (Exception e) {
                System.out.println("Exception: " + e);
            }
        }
    }
}

class Main {
    public static void main(final String[] args) {
        final Thread[] threads = new Thread[6];
        final SharedFifoQueue sqf = new SharedFifoQueue(20);

        for (int n = 1; n < threads.length; n += 2) {
            final ProducerThread pt = new ProducerThread(sqf);
            final ConsumerThread ct = new ConsumerThread(sqf);

            threads[n - 1] = new Thread(pt);
            threads[n] = new Thread(ct);

            System.out.println("Start Producer Thread: " + threads[n - 1].getName());
            threads[n - 1].start();

            System.out.println("Start Consumer Thread: " + threads[n].getName());
            threads[n].start();
        }
    }
}

/**
 * MonitorBoundedCounter
 *
 * @author Letícia Mazzo Portela
 * @since Aug/2020
 */
class BoundedCounter extends Thread {
    private int count = 0, min = 3, max = 5;

    public synchronized void increment(String name) {
        while (count == max) {
            try {
                System.out.println("Thread " + name + " blocked");
                wait();
            } catch (InterruptedException e) {
                System.out.println("Interrupting wait: " + e);
            }
        }
        count += 1;
        notify();
    }

    public synchronized void decrement(String name) {
        while (count == min) {
            try {
                System.out.println("Thread " + name + " blocked");
                wait();
            } catch (InterruptedException e) {
                System.out.println("Interrupting wait: " + e);
            }
        }
        count -= 1;
        notify();
    }

    @Override
    public void run() {
        final String name = Thread.currentThread().getName();

        while (count <= max) {
            increment(name);
            System.out.println("Counter increased to " + count + " for thread " + name);
        }

        while (count >= min) {
            decrement(name);
            System.out.println("Counter decremented to " + count + " for thread " + name);
        }
    }
}

class MonitorBoundedCounter {
    public static void main(final String[] args) {
        final Thread[] threads = new Thread[2];

        for (int n = 0; n < threads.length; n += 1) {
            final BoundedCounter tc = new BoundedCounter();
            threads[n] = new Thread(tc);
            System.out.println("Start Thread " + threads[n].getName());
            threads[n].start();
        }
    }
}

